export const additionalChallenges=[
 {id:'first-not-less',lesson:'ds-lowerbound',title:'手写：找到第一个不小于目标的位置',level:'入门',kind:'C/C++ 编程',prompt:'在非递减数组中返回第一个值不小于 target 的下标；都小于目标时返回 n。采用半开区间，允许重复元素。',cases:['[1,2,2,5]，target=2 → 1','[]，target=7 → 0','[1,3]，target=4 → 2（尾后位置）'],hint:'a[mid]>=target 时保留 mid 为边界候选，令 hi=mid；否则 lo=mid+1。',solution:'size_t first_not_less(const int *a, size_t n, int target) {\n    size_t lo=0, hi=n;\n    while (lo<hi) {\n        size_t mid=lo+(hi-lo)/2;\n        if (a[mid]<target) lo=mid+1;\n        else hi=mid;\n    }\n    return lo;\n}',analysis:'循环不变量：lo 左边均小于 target，hi 及右边均不小于 target；中间保留未知区。每轮缩小，lo==hi 是分界点。返回 n 合法但不可读 a[n]。时间 O(log n)，空间 O(1)。n>0 时 a 必须指向至少 n 个有效元素。',links:[['相关力扣 35：搜索插入位置（原题元素不重复）','https://leetcode.cn/problems/search-insert-position/']]},
 {id:'prefix-range',lesson:'ds-prefix',title:'手写：多次查询区间和',level:'入门',kind:'C/C++ 编程',prompt:'数组构造后不再修改，先建立前缀和，再返回闭区间 [left,right] 的总和。范围非法返回失败。假设所有累计值可由 int64_t 表示。',cases:['[2,4,1,3]，left=1，right=2 → 5','left>right 或 right>=n → 失败','left=right=0 → 第一个元素'],hint:'prefix[k] 存前 k 项之和；闭区间要把 right 转为右侧半开边界 right+1。',solution:'bool build_prefix(const int *a, size_t n, int64_t *p) {\n    if (!p || (n && !a)) return false;\n    p[0]=0;\n    for (size_t i=0;i<n;++i) p[i+1]=p[i]+a[i];\n    return true;\n}\nbool range_sum(const int64_t *p, size_t n,\n               size_t left, size_t right, int64_t *out) {\n    if (!p || !out || left>right || right>=n) return false;\n    *out=p[right+1]-p[left];\n    return true;\n}',analysis:'调用者提供 n+1 个 int64_t 的前缀缓冲。初始化扫描一次 O(n)，查询固定两次读取和一次减法 O(1)，额外空间 O(n)。p[right+1] 包含 right 元素，而 p[left] 不包含 left，相减恰好保留闭区间。要保证前缀累加与区间结果都不会溢出。',links:[['力扣 303：区域和检索（数组不可变）','https://leetcode.cn/problems/range-sum-query-immutable/']]},
 {id:'overlap-shift',lesson:'c-memcpy',title:'手写：数组内安全右移字节',level:'入门',kind:'C 编程',prompt:'同一缓冲区内把前 len 字节向右移动一位，索引 0 保持原值；容量至少 len+1。实现时不用 memcpy/memmove，先检查边界。',cases:['ABCDE，len=4 → AABCD','len=0 → 成功且不修改','len>=capacity → 失败'],hint:'从后往前写。用 i>0 控制循环，避免 size_t 在 0 时减到最大值。',solution:'bool shift_right(unsigned char *buf, size_t capacity, size_t len) {\n    if (!buf || len>=capacity) return false;\n    for (size_t i=len;i>0;--i) buf[i]=buf[i-1];\n    return true;\n}',analysis:'从 len 向 1 写，每次源 i-1 尚未被覆盖；若从左到右，先写 buf[1]=buf[0] 后，下一次读取 buf[1] 就是被覆盖的数据。时间 O(len)，空间 O(1)。len>=capacity 的比较避免 len+1 自身溢出。真实接口也可直接在验证容量后使用 memmove(buf+1,buf,len)。',links:[]},
 {id:'safe-sorter-fsm',lesson:'e-fsm',title:'设计：带超时的分拣状态机',level:'进阶',kind:'嵌入式场景',prompt:'系统有 IDLE、WAIT_POSITION、ACTUATE、FAULT 四态；START 启动传送，POSITION 允许分拣，DONE 结束，等待或动作阶段 TIMEOUT 必须安全停止。列出非法事件的处理规则。',cases:['IDLE + START → WAIT_POSITION','WAIT_POSITION + TIMEOUT → FAULT，停止电机','IDLE + POSITION → 忽略并记录，禁止分拣'],hint:'先定义每态能接受什么事件，所有错误路径明确输出状态，故障只能在安全复位条件满足时解除。',solution:'enum State { IDLE, WAIT_POSITION, ACTUATE, FAULT };\nenum Event { START, POSITION, DONE, TIMEOUT, RESET };\nvoid dispatch(enum Event e) {\n    if ((state==WAIT_POSITION || state==ACTUATE) && e==TIMEOUT) {\n        motor_stop(); actuator_stop(); state=FAULT; return;\n    }\n    switch (state) {\n    case IDLE:\n        if (e==START) { motor_start(); arm_timeout(); state=WAIT_POSITION; }\n        else log_ignored(e);\n        break;\n    case WAIT_POSITION:\n        if (e==POSITION) { motor_stop(); actuator_start(); arm_timeout(); state=ACTUATE; }\n        else log_ignored(e);\n        break;\n    case ACTUATE:\n        if (e==DONE) { actuator_stop(); cancel_timeout(); state=IDLE; }\n        else log_ignored(e);\n        break;\n    case FAULT:\n        if (e==RESET && safe_to_reset()) { cancel_timeout(); state=IDLE; }\n        else log_ignored(e);\n        break;\n    }\n}',analysis:'这是接口示意，输出函数、超时实现和安全判定需按硬件实现。超时必须和当前状态/操作编号匹配，避免旧计时器事件误伤新动作；事件由单一控制任务串行处理。重复 START 不重复启动，POSITION 仅在等待态触发动作，故障态不自动恢复输出。每次分发固定状态数，时间 O(1)，额外状态 O(1)。',links:[]}
];
